// Some portions generated by Claude
import assert from 'node:assert/strict';
import test from 'node:test';
import { RDF_TYPE } from '../../../main/frontend/graph-explorer/graph-canvas-scope.ts';
import { withCollapsedClassLinks } from '../../../main/frontend/graph-explorer/graph-class-links.ts';
import { routeDrawnEdges } from '../../../main/frontend/graph-explorer/graph-edge-routing.ts';
import { computeGraphLayout } from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';

// Seven people of class Person in a chain of acquaintances; two cities of class City.
function people() {
  const nodes = [{ id: 'urn:Person', label: 'Person', kind: 'iri' }, { id: 'urn:City', label: 'City', kind: 'iri' }];
  const edges = [];
  for (let i = 0; i < 7; i++) {
    nodes.push({ id: `urn:p${i}`, label: `Person ${i}`, kind: 'iri', types: [{ id: 'urn:Person', label: 'Person' }], x: i * 200, y: 0 });
    edges.push({ id: `p${i}-type`, source: `urn:p${i}`, target: 'urn:Person', predicate: RDF_TYPE, label: 'type' });
    if (i) edges.push({ id: `p${i}-knows`, source: `urn:p${i - 1}`, target: `urn:p${i}`, predicate: 'urn:knows', label: 'knows' });
  }
  for (let i = 0; i < 2; i++) {
    nodes.push({ id: `urn:c${i}`, label: `City ${i}`, kind: 'iri', x: i * 200, y: 300 });
    edges.push({ id: `c${i}-type`, source: `urn:c${i}`, target: 'urn:City', predicate: RDF_TYPE, label: 'type' });
    edges.push({ id: `c${i}-home`, source: `urn:p${i}`, target: `urn:c${i}`, predicate: 'urn:livesIn', label: 'lives in' });
  }
  nodes[0].x = 600; nodes[0].y = 200; nodes[1].x = 100; nodes[1].y = 500;
  return { nodes, edges, revision: 1 };
}

test('links to a class with many instances are collapsed; links to a small class stay', () => {
  const graph = people();
  const { graph: shown, collapsed } = withCollapsedClassLinks(graph);
  assert.deepEqual(collapsed.map((edge) => edge.id).sort(), Array.from({ length: 7 }, (_, i) => `p${i}-type`).sort());
  assert.ok(shown.edges.some((edge) => edge.id === 'c0-type'), 'City has two instances: its links stay');
  assert.equal(shown.nodes, graph.nodes, 'the class card itself stays');
  assert.equal(withCollapsedClassLinks(graph).graph, shown, 'computed once per graph');
  const plain = { ...graph, edges: graph.edges.filter((edge) => edge.predicate !== RDF_TYPE) };
  assert.equal(withCollapsedClassLinks(plain).graph, plain, 'nothing to collapse: the graph itself');
});

test('collapsed class links are neither routed in the app nor by the layout', async () => {
  const graph = people();
  const bends = routeDrawnEdges(graph, true, 2);
  assert.ok(![...bends.keys()].some((id) => id.startsWith('p') && id.endsWith('-type')), [...bends.keys()].join(', '));
  assert.ok(bends.has('c0-type'));
  const result = await computeGraphLayout(graph, { mode: 'network' });
  assert.ok(![...result.bends.keys()].some((id) => id.startsWith('p') && id.endsWith('-type')), [...result.bends.keys()].join(', '));
  assert.equal(result.positions.size, graph.nodes.length);
});
